mapper.select:
 select p.*,

CONCAT(#{bpmUrlPre},'&formInstanceId=',p.id,'&processId=',p.BPM_FLOW_ID) bpm_url

 from safety_park_power_process p

 order by p.CREATE_TIME desc


         limit ${offset}, ${limit}


         limit ${limit}

select employee_no,employee_name,group_concat(car_no) as car_no from safety_employee_private_car where myself_car = '是' and lock_flag != '1' and delete_flag = '0' and employee_no in
#{ll}
group by employee_no,employee_name

select employee_no as emp_no,group_concat(car_no) as car_no from safety_employee_private_car where lock_flag != '1' and delete_flag = '0' and employee_no in
#{ll.empNo}
group by employee_no

select employee_no as emp_no,group_concat(car_no) as car_no from safety_employee_private_car where lock_flag != '1' and delete_flag = '0' and employee_no in
#{ll}
group by employee_no

select m.emp_no,m.emp_name,m.phone_no,group_concat(ei.FACTORY_ID) as factory_id,max(ei.POWER_END_TIME) as power_end_time from safety_employee_message m left join safety_park_employee_power_info ei on m.emp_no = ei.EMPLOYEE_CODE and ei.IS_DELETE = '0' where status = 'NORMAL'
and m.user_type = #{userType}
and emp_no in
#{item}
group by m.emp_no, m.emp_name, m.phone_no
